    OR NOT EXISTS(SELECT 1 FROM job_idempotency_keys c JOIN pgboss.job j ON j.id=c.job_id AND j.name=c.job_name WHERE c.job_id=NEW.original_job_id AND c.job_name='subscriptions.applyGrossProration' AND c.payload_hash=NEW.job_claim_digest AND j.data=NEW.original_task)
    OR(NEW.original_trial_ends_at IS NULL AND NOT EXISTS(SELECT 1 FROM invoices i WHERE i.id=NEW.debit_invoice_id AND i.source_type='subscription' AND i.source_id=parent.id::text||':proration:'||NEW.id::text AND i.contact_id=parent.contact_id AND i.currency=parent.currency
     AND i.status='paid' AND i.paid_minor+i.credited_minor=i.total_minor AND i.refunded_minor=0 AND i.paid_at<=NEW.effective_at AND i.total_minor=NEW.debit_net_minor+NEW.debit_tax_minor AND i.tax_minor=NEW.debit_tax_minor)) THEN
    RAISE EXCEPTION 'Only exact fully paid consideration inside the real accepted window can activate new access; late or partial money remains recovery debt' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO previous FROM subscription_commercial_terms WHERE id=NEW.previous_terms_id;
 IF parent.id IS NULL OR parent.merchant_scope_version<>1 OR parent.status NOT IN('active','trialing') OR parent.signup_pending OR parent.pending_plan_id IS NOT NULL OR parent.cancel_at_period_end OR parent.cancelled_at IS NOT NULL
  OR scope.subscription_id IS NULL OR(parent.billing_mode='provider' AND NOT controlled)
  OR(parent.billing_mode<>'provider' AND(parent.billing_mode NOT IN('manual','platform') OR resource.operation_revision<>0 OR resource.state<>'uncreated' OR resource.recovery_pending OR resource.provider_subscription_ref IS NOT NULL))
  OR previous.id IS NULL OR previous.subscription_id<>parent.id OR previous.snapshot->>'proration' IS DISTINCT FROM 'create_prorations'
  OR EXISTS(SELECT 1 FROM subscription_commercial_terms other WHERE other.subscription_id=parent.id AND other.revision>previous.revision)
  OR(previous.effective_period_start>=parent.current_period_end AND NOT EXISTS(SELECT 1 FROM subscription_prorations prior WHERE prior.terms_id=previous.id AND prior.state='applied'))
  OR NEW.original_period_start<>parent.current_period_start OR NEW.original_period_end<>parent.current_period_end OR NEW.effective_at<=clock_timestamp()
  OR NEW.proposed_period_start<>NEW.effective_at OR(NOT controlled AND NEW.proposed_period_end<>parent.current_period_end)
  OR(controlled AND(NEW.proposed_period_end IS DISTINCT FROM(q.review->'calendar'->>'proposedPeriodEnd')::timestamptz
   OR NEW.snapshot IS DISTINCT FROM q.review->'quote'->'snapshot' OR NEW.accepted_quote_digest IS DISTINCT FROM q.quote_digest
   OR NEW.debit_net_minor::text IS DISTINCT FROM q.review->>'debitNetMinor' OR NEW.debit_tax_minor::text IS DISTINCT FROM q.review->>'debitTaxMinor'
   OR NEW.credit_net_minor::text IS DISTINCT FROM q.review->>'creditNetMinor' OR NEW.credit_tax_minor::text IS DISTINCT FROM q.review->>'creditTaxMinor')) OR NEW.profile_id<>scope.tax_profile_id
  OR NEW.snapshot->>'version' IS DISTINCT FROM '1' OR NEW.snapshot->>'currency' IS DISTINCT FROM parent.currency OR NEW.snapshot->>'billingMode' IS DISTINCT FROM parent.billing_mode
  OR NEW.debit_tax_quote->>'subtotalMinor' IS DISTINCT FROM NEW.debit_net_minor::text OR NEW.debit_tax_quote->>'taxMinor' IS DISTINCT FROM NEW.debit_tax_minor::text
  OR NEW.debit_tax_quote->>'totalMinor' IS DISTINCT FROM(NEW.debit_net_minor+NEW.debit_tax_minor)::text OR NOT coalesce(NEW.debit_tax_quote->>'quoteDigest' ~ '^[a-f0-9]{64}$',false)
  OR NEW.state<>'accepted' OR NEW.original_job_id IS NOT NULL OR NEW.original_task IS NOT NULL OR NEW.credit_note_id IS NOT NULL OR NEW.debit_invoice_id IS NOT NULL
  OR EXISTS(SELECT 1 FROM subscription_prorations other WHERE other.subscription_id=parent.id AND other.state NOT IN('applied','cancelled')) THEN
  RAISE EXCEPTION 'Accept one fresh original gross proration with its actual paid period, merchant and quiescent local-calendar authority' USING ERRCODE='23514'; END IF;
 IF parent.status='trialing' THEN
  IF NEW.original_trial_ends_at IS DISTINCT FROM parent.trial_ends_at OR NEW.original_trial_ends_at IS DISTINCT FROM parent.current_period_end OR NEW.original_invoice_id IS NOT NULL OR NEW.original_invoice_line_id IS NOT NULL THEN
   RAISE EXCEPTION 'An uncharged trial preserves its accepted end and has no old paid principal or credit' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO source FROM invoices WHERE id=NEW.original_invoice_id;
  SELECT * INTO line FROM invoice_lines WHERE id=NEW.original_invoice_line_id;
  IF source.refunded_minor<>0 THEN
   atomic_decl:=q.review->'atomicCreditFeeDeclaration';atomic_sources:=q.review->'feeReview'->'sources';
   atomic_siblings_ok:=controlled IS TRUE AND freeholder_credit_atomic_fee_ready()
    AND atomic_decl->>'protocol'='freeholder.atomic-credit-fee-declaration.v1' AND atomic_decl->>'quoteId'=q.id::text AND atomic_decl->>'resourceId'=q.resource_id::text
    AND atomic_decl->>'subscriptionId'=parent.id::text AND atomic_decl->>'plannedProrationId'=NEW.id::text
    AND atomic_decl->>'originalInvoiceId'=source.id::text AND atomic_decl->>'originalInvoiceLineId'=line.id::text
    AND atomic_decl->>'digest' ~ '^[a-f0-9]{64}$' AND atomic_decl->>'authentication' ~ '^[a-f0-9]{64}$'
    AND jsonb_typeof(atomic_decl->'fundings')='array' AND jsonb_array_length(atomic_decl->'fundings') BETWEEN 1 AND 1000
    AND jsonb_typeof(atomic_sources)='array' AND jsonb_array_length(atomic_sources) BETWEEN 1 AND 1000
    AND NOT EXISTS(SELECT 1 FROM payments original_payment WHERE original_payment.invoice_id=source.id AND original_payment.status IN('created','processing'))
    AND(select coalesce(sum(original_payment.amount_minor),0) from payments original_payment where original_payment.invoice_id=source.id and original_payment.status='succeeded')=source.paid_minor
    AND(select coalesce(sum(original_payment.refunded_minor),0) from payments original_payment where original_payment.invoice_id=source.id and original_payment.status='succeeded')=source.refunded_minor
    AND(select count(*) from freeholder_controlled_atomic_refund_targets(source.id) original_target where original_target.known)=(select count(*) from payments original_payment where original_payment.invoice_id=source.id and original_payment.status='succeeded')
    AND NOT EXISTS(SELECT 1 FROM payments original_payment LEFT JOIN LATERAL freeholder_controlled_atomic_refund_bank_state(original_payment.id) original_bank ON true
     LEFT JOIN LATERAL freeholder_controlled_atomic_refund_fee_state(original_payment.id) original_fee ON true
     WHERE original_payment.invoice_id=source.id AND original_payment.status='succeeded' AND(original_bank.known IS DISTINCT FROM true OR original_bank.refunded_minor IS DISTINCT FROM original_payment.refunded_minor::float8
      OR original_fee.known IS DISTINCT FROM true OR original_fee.reconciled IS DISTINCT FROM true
      OR EXISTS(SELECT 1 FROM freeholder_atomic_fee_return_resources(original_payment.id) actual_return WHERE NOT actual_return.known OR actual_return.pending)
      OR original_payment.refunded_minor>0 AND EXISTS(SELECT 1 FROM invoice_credit_funding original_loan WHERE original_loan.source_payment_id=original_payment.id)));
   IF atomic_siblings_ok IS TRUE THEN
    IF(select count(*) from jsonb_array_elements(atomic_sources) source_value(value))<>(select count(DISTINCT(source_value.value->>'sourcePaymentId',source_value.value->>'sourceApplicationId')) from jsonb_array_elements(atomic_sources) source_value(value)) THEN atomic_siblings_ok:=false;END IF;
    FOR atomic_source IN SELECT source_value.value FROM jsonb_array_elements(atomic_sources) source_value(value) LOOP
     IF NOT freeholder_controlled_bank_minor(atomic_source->'amountMinor') OR(atomic_source->>'amountMinor')::numeric<=0 THEN atomic_siblings_ok:=false;EXIT;END IF;
     SELECT original_payment.* INTO atomic_payment FROM payments original_payment WHERE original_payment.id=(atomic_source->>'sourcePaymentId')::uuid;
     IF atomic_payment.id IS NULL OR atomic_payment.status IS DISTINCT FROM 'succeeded' OR atomic_payment.refunded_minor<>0 OR atomic_payment.currency IS DISTINCT FROM source.currency
      OR freeholder_proration_principal_capacity(atomic_payment.id,(atomic_source->>'sourceApplicationId')::uuid)<(atomic_source->>'amountMinor')::numeric THEN atomic_siblings_ok:=false;EXIT;END IF;
     IF atomic_source->>'sourceApplicationId' IS NULL THEN
      IF atomic_payment.invoice_id IS DISTINCT FROM source.id THEN atomic_siblings_ok:=false;EXIT;END IF;
     ELSE
      SELECT original_application.* INTO atomic_application FROM invoice_credit_applications original_application WHERE original_application.reservation_id=(atomic_source->>'sourceApplicationId')::uuid;
      SELECT original_reservation.* INTO atomic_reservation FROM invoice_credit_reservations original_reservation WHERE original_reservation.id=atomic_application.reservation_id;
      SELECT original_funding.* INTO atomic_funding FROM invoice_credit_funding original_funding WHERE original_funding.id=atomic_reservation.funding_id;
      IF atomic_application.reservation_id IS NULL OR atomic_application.invoice_id IS DISTINCT FROM source.id OR atomic_funding.source_payment_id IS DISTINCT FROM atomic_payment.id
       OR EXISTS(SELECT 1 FROM invoice_credit_releases actual_release WHERE actual_release.reservation_id=atomic_application.reservation_id) THEN atomic_siblings_ok:=false;EXIT;END IF;
     END IF;
     SELECT freeholder_controlled_cash_scope(original_batch.collection_id) INTO atomic_scope FROM controlled_cash_application_links original_link JOIN controlled_cash_application_batches original_batch ON original_batch.id=original_link.batch_id WHERE original_link.payment_id=atomic_payment.id;
     IF atomic_scope IS NULL THEN atomic_siblings_ok:=false;EXIT;END IF;
     FOR atomic_required_resource IN SELECT original_resource FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'resources')) original_resource LOOP PERFORM freeholder_controlled_cash_require_prefix(atomic_required_resource);END LOOP;
     FOR atomic_required_key IN SELECT 'payment:'||actual_id::text FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'payments')) actual_id
      UNION SELECT 'invoice:'||actual_id::text FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'invoices')) actual_id
      UNION SELECT 'credit-note:'||actual_id::text FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'notes')) actual_id
      UNION SELECT 'merchant-return-read:'||actual_id::text FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'inspections')) actual_id
      UNION SELECT 'merchant-fee-invocation:'||actual_id::text FROM unnest(freeholder_controlled_cash_scope_ids(atomic_scope,'payments')) actual_id
      UNION SELECT 'subscription-cash:'||(actual_namespace->>'platform')||':'||coalesce(actual_namespace->>'account','')||':'||(actual_namespace->>'intent') FROM jsonb_array_elements(atomic_scope->'namespaces') actual_namespace LOOP
      IF atomic_required_key IS NULL OR NOT EXISTS(SELECT 1 FROM pg_locks actual_lock WHERE actual_lock.pid=pg_backend_pid() AND actual_lock.locktype='advisory' AND actual_lock.granted
       AND actual_lock.database=(SELECT oid FROM pg_database WHERE datname=current_database()) AND actual_lock.mode='ExclusiveLock' AND actual_lock.objsubid=1
       AND actual_lock.classid::bigint=(CASE WHEN hashtext(atomic_required_key)<0 THEN 4294967295::bigint ELSE 0::bigint END) AND actual_lock.objid::bigint=(hashtext(atomic_required_key)::bigint & 4294967295::bigint)) THEN
       RAISE EXCEPTION 'Genuine B birth requires the complete held source/canonical/cash/callback prefix before any new canonical target' USING ERRCODE='23514';END IF;
     END LOOP;
     IF EXISTS(SELECT 1 FROM jsonb_array_elements(atomic_decl->'fundings') declared_source(value) WHERE declared_source.value->>'sourcePaymentId'=atomic_payment.id::text AND declared_source.value->>'sourceApplicationId' IS NOT DISTINCT FROM atomic_source->>'sourceApplicationId') THEN
      SELECT current_candidate.* INTO atomic_candidate FROM freeholder_atomic_credit_fee_partition(atomic_payment.id,(atomic_source->>'sourceApplicationId')::uuid,(atomic_source->>'amountMinor')::bigint) current_candidate;
      IF atomic_candidate.known IS DISTINCT FROM true OR atomic_source->>'feeObligationMinor' IS DISTINCT FROM atomic_candidate.take_assigned_fee_minor::text
       OR atomic_source->>'feeProvenCollectedMinor' IS DISTINCT FROM atomic_candidate.take_collected_fee_minor::text
       OR atomic_source->>'feeCollectionState' IS DISTINCT FROM(CASE WHEN atomic_candidate.take_assigned_fee_minor=0 THEN 'not_due' WHEN atomic_candidate.take_owed_fee_minor=0 THEN 'verified_collected' ELSE 'owed' END)
       OR atomic_source->'feeUnexpected' IS DISTINCT FROM 'false'::jsonb THEN atomic_siblings_ok:=false;EXIT;END IF;
     END IF;
     atomic_total:=atomic_total+(atomic_source->>'amountMinor')::numeric;
    END LOOP;
    IF atomic_total IS DISTINCT FROM NEW.credit_net_minor+NEW.credit_tax_minor
     OR EXISTS(SELECT 1 FROM jsonb_array_elements(atomic_decl->'fundings') declared_source(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(atomic_sources) original_source(value)
      WHERE declared_source.value->>'sourcePaymentId'=original_source.value->>'sourcePaymentId' AND declared_source.value->>'sourceApplicationId' IS NOT DISTINCT FROM original_source.value->>'sourceApplicationId'
       AND declared_source.value->>'amountMinor'=original_source.value->>'amountMinor' AND declared_source.value->>'feeEvidenceDigest'=original_source.value->>'feeEvidenceDigest')) THEN atomic_siblings_ok:=false;END IF;
   END IF;
  END IF;
  IF source.id IS NULL OR source.source_type<>'subscription' OR split_part(source.source_id,':',1)<>parent.id::text OR source.contact_id<>parent.contact_id OR source.currency<>parent.currency OR source.status<>'paid'
   OR source.paid_minor+source.credited_minor<>source.total_minor OR(source.refunded_minor<>0 AND atomic_siblings_ok IS DISTINCT FROM true) OR line.id IS NULL OR line.invoice_id<>source.id OR line.source_type<>'subscription' OR line.source_id<>parent.id::text OR line.discount_minor<>0 OR line.quantity_micros<>1000000
   OR NEW.basis_period_end<>parent.current_period_end OR NOT((source.source_id=parent.id::text||':'||to_char(parent.current_period_start AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AND NEW.basis_period_start=parent.current_period_start AND line.snapshot->>'subscriptionComponent'='period')
    OR EXISTS(SELECT 1 FROM subscription_prorations prior WHERE prior.debit_invoice_id=source.id AND prior.state='applied' AND prior.plan_id=parent.plan_id AND prior.effective_at=NEW.basis_period_start AND line.snapshot->>'subscriptionProrationId'=prior.id::text)) THEN
   RAISE EXCEPTION 'Only the exact original paid period line and its retained ancestor consideration can fund unused credit' USING ERRCODE='23514'; END IF;
  old_net:=floor(line.subtotal_minor::numeric*extract(epoch FROM(NEW.basis_period_end-NEW.effective_at))/extract(epoch FROM(NEW.basis_period_end-NEW.basis_period_start))+0.5);
  old_tax:=floor(line.tax_minor::numeric*extract(epoch FROM(NEW.basis_period_end-NEW.effective_at))/extract(epoch FROM(NEW.basis_period_end-NEW.basis_period_start))+0.5);
  IF controlled THEN
   new_net:=floor((NEW.snapshot->>'periodAmountMinor')::numeric*extract(epoch FROM((q.review->'calendar'->>'expectedProviderPeriodEnd')::timestamptz-NEW.effective_at))
    /nullif(extract(epoch FROM((q.review->'calendar'->>'expectedProviderPeriodEnd')::timestamptz-(q.review->'calendar'->>'expectedProviderPeriodStart')::timestamptz)),0)+0.5);
   IF new_net IS NULL OR new_net<0 OR NEW.debit_net_minor<>new_net THEN RAISE EXCEPTION 'Retain the exact actual provider preview calendar with the shared canonical rounding engine' USING ERRCODE='23514';END IF;
  ELSE
  new_net:=floor((NEW.snapshot->>'periodAmountMinor')::numeric*extract(epoch FROM(parent.current_period_end-NEW.effective_at))/extract(epoch FROM(parent.current_period_end-parent.current_period_start))+0.5);
  END IF;
  IF NEW.credit_net_minor<>old_net OR NEW.credit_tax_minor<>old_tax OR NEW.debit_net_minor<>new_net THEN RAISE EXCEPTION 'Preserve separately rounded actual old principal/tax and the accepted new gross unused rate exactly' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
